package com.cob.emr.ddd.domain.medicalnote.model.billing;import com.cob.emr.ddd.domain.medicalnote.model.objective.ObjectiveFindings;import com.cob.emr.ddd.domain.medicalnote.model.objective.PerformedIntervention;import lombok.Builder;import lombok.Getter;import java.util.ArrayList;import java.util.List;import java.util.stream.Collectors;@Getter@Builder(toBuilder = true)public class BillingInformation {        private final List<TimedCode> timedCodes;    private final List<UntimedCode> untimedCodes;    private final List<String> supplies;    private final List<String> casts;    private final List<String> braces;    private final List<String> splintsOrthotics;    private final String respiratory;    private final String nerveConduction;    private final boolean dailyNoteIncluded;    private final String calendarMonth;    private final String preTreatment;    private final String postTreatment;    private final String objectiveFindings;    private final String instructionsTxt;    private final String otherTreatmentProcedures;        public void validate() {        if ((timedCodes == null || timedCodes.isEmpty()) &&             (untimedCodes == null || untimedCodes.isEmpty())) {            throw new IllegalStateException("At least one billing code is required");        }                if (!validate8MinuteRule()) {            throw new IllegalStateException("Billing does not comply with 8-minute rule");        }    }        public boolean hasEvaluationCode() {        if (untimedCodes == null) return false;        return untimedCodes.stream()            .anyMatch(UntimedCode::isEvaluationCode);    }        public BillingInformation excludeEvaluationCodes() {        if (untimedCodes == null) return this;                List<UntimedCode> filtered = untimedCodes.stream()            .filter(code -> !code.isEvaluationCode())            .collect(Collectors.toList());                    return this.toBuilder()            .untimedCodes(filtered)            .build();    }        public int calculateTotalUnits() {        if (timedCodes == null) return 0;        return timedCodes.stream()            .mapToInt(TimedCode::getUnits)            .sum();    }        public boolean validate8MinuteRule() {        if (timedCodes == null || timedCodes.isEmpty()) return true;                int totalMinutes = timedCodes.stream()            .mapToInt(TimedCode::getDurationMinutes)            .sum();                    int totalUnits = calculateTotalUnits();                if (totalMinutes < 8) return totalUnits == 0;                int expectedMinUnits = (totalMinutes - 8) / 15 + 1;        int expectedMaxUnits = (totalMinutes + 7) / 15;                return totalUnits >= expectedMinUnits && totalUnits <= expectedMaxUnits;    }        public ObjectiveFindings toObjectiveFindings() {        List<PerformedIntervention> interventions = new ArrayList<>();                if (timedCodes != null) {            timedCodes.stream()                .map(code -> PerformedIntervention.builder()                    .cptCode(code.getCptCode())                    .description(code.getDescription())                    .durationMinutes(code.getDurationMinutes())                    .units(code.getUnits())                    .build())                .forEach(interventions::add);        }                if (untimedCodes != null) {            untimedCodes.stream()                .filter(code -> !code.isEvaluationCode())                .map(code -> PerformedIntervention.builder()                    .cptCode(code.getCptCode())                    .description(code.getDescription())                    .build())                .forEach(interventions::add);        }                return ObjectiveFindings.builder()            .performedInterventions(interventions)            .preTreatmentFindings(preTreatment)            .postTreatmentFindings(postTreatment)            .clinicalObservations(objectiveFindings)            .instructions(instructionsTxt)            .build();    }}
